# Test Script for brglmFit_trustregion on Binomial Models
# Validates trust region implementation against quasi-Fisher scoring
# Generated by Claude sonnet 4.5

separator <- strrep("=", 70)

# ============================================================================
# TEST 1: Simple logistic regression (lizards dataset from brglm2)
# ============================================================================

cat("TEST 1: Lizards dataset (standard logistic regression)\n")
cat(separator, "\n")

data("lizards", package = "brglm2")

# Quasi-Fisher (reference)
fit_qf <- glm(cbind(grahami, opalinus) ~ height + diameter + light + time, 
              family = binomial(logit), 
              data = lizards,
              method = "brglmFit")

# Trust region
fit_tr <- glm(cbind(grahami, opalinus) ~ height + diameter + light + time, 
              family = binomial(logit), 
              data = lizards,
              method = "brglmFit_trustregion")

cat("\nQuasi-Fisher coefficients:\n")
print(coef(fit_qf))

cat("\nTrust Region coefficients:\n")
print(coef(fit_tr))

cat("\nDifference:\n")
print(coef(fit_tr) - coef(fit_qf))

cat("\nMax absolute difference:", max(abs(coef(fit_tr) - coef(fit_qf))), "\n")

# Check convergence
cat("\nQuasi-Fisher converged:", fit_qf$converged, "in", fit_qf$iter, "iterations\n")
cat("Trust Region converged:", fit_tr$converged, "in", fit_tr$iter, "iterations\n")

cat("\n")


# ============================================================================
# TEST 2: Separation case (endometrial dataset)
# ============================================================================

cat("TEST 2: Endometrial dataset (separation present)\n")
cat(separator, "\n")

data("endometrial", package = "brglm2")

# Quasi-Fisher
fit_qf2 <- glm(HG ~ NV + PI + EH, 
               data = endometrial,
               family = binomial("probit"),
               method = "brglmFit")

# Trust region
fit_tr2 <- glm(HG ~ NV + PI + EH, 
               data = endometrial,
               family = binomial("probit"),
               method = "brglmFit_trustregion")

cat("\nQuasi-Fisher coefficients:\n")
print(coef(fit_qf2))

cat("\nTrust Region coefficients:\n")
print(coef(fit_tr2))

cat("\nDifference:\n")
print(coef(fit_tr2) - coef(fit_qf2))

cat("\nMax absolute difference:", max(abs(coef(fit_tr2) - coef(fit_qf2))), "\n")

cat("\nQuasi-Fisher converged:", fit_qf2$converged, "in", fit_qf2$iter, "iterations\n")
cat("Trust Region converged:", fit_tr2$converged, "in", fit_tr2$iter, "iterations\n")

cat("\n")


# ============================================================================
# TEST 3: Synthetic data - complete separation
# ============================================================================

cat("TEST 3: Synthetic data with complete separation\n")
cat(separator, "\n")

set.seed(123)
n <- 50
x1 <- rnorm(n)
x2 <- rnorm(n)
# Create perfect separation
y <- as.numeric(x1 + 2*x2 > 0)

synthetic_data <- data.frame(y = y, x1 = x1, x2 = x2)

cat("\nSeparation check: perfect separation =", 
    all(y[x1 + 2*x2 > 0] == 1) & all(y[x1 + 2*x2 <= 0] == 0), "\n")

# Quasi-Fisher
fit_qf3 <- glm(y ~ x1 + x2, 
               data = synthetic_data,
               family = binomial(logit),
               method = "brglmFit")

# Trust region
fit_tr3 <- glm(y ~ x1 + x2, 
               data = synthetic_data,
               family = binomial(logit),
               method = "brglmFit_trustregion")

cat("\nQuasi-Fisher coefficients:\n")
print(coef(fit_qf3))

cat("\nTrust Region coefficients:\n")
print(coef(fit_tr3))

cat("\nDifference:\n")
print(coef(fit_tr3) - coef(fit_qf3))

cat("\nMax absolute difference:", max(abs(coef(fit_tr3) - coef(fit_qf3))), "\n")

cat("\nQuasi-Fisher converged:", fit_qf3$converged, "in", fit_qf3$iter, "iterations\n")
cat("Trust Region converged:", fit_tr3$converged, "in", fit_tr3$iter, "iterations\n")

cat("\n")


# ============================================================================
# TEST 4: Different bias reduction types
# ============================================================================

cat("TEST 4: Different bias reduction types\n")
cat(separator, "\n")

types <- c("AS_mean", "AS_median", "AS_mixed", "ML")

for (type in types) {
    cat("\nType:", type, "\n")
    
    fit_qf_type <- glm(cbind(grahami, opalinus) ~ height + diameter + light + time, 
                       family = binomial(logit), 
                       data = lizards,
                       method = "brglmFit",
                       type = type)
    
    fit_tr_type <- glm(cbind(grahami, opalinus) ~ height + diameter + light + time, 
                       family = binomial(logit), 
                       data = lizards,
                       method = "brglmFit_trustregion",
                       type = type)
    
    max_diff <- max(abs(coef(fit_tr_type) - coef(fit_qf_type)))
    cat("  Max coefficient difference:", max_diff, "\n")
    cat("  QF iterations:", fit_qf_type$iter, "| TR iterations:", fit_tr_type$iter, "\n")
}

cat("\n")


# ============================================================================
# TEST 5: Numerical properties check
# ============================================================================

cat("TEST 5: Numerical properties (lizards dataset)\n")
cat(separator, "\n")

# Check that key properties are preserved
cat("\nDeviance comparison:\n")
cat("  Quasi-Fisher:", fit_qf$deviance, "\n")
cat("  Trust Region:", fit_tr$deviance, "\n")
cat("  Difference:", abs(fit_tr$deviance - fit_qf$deviance), "\n")

cat("\nAIC comparison:\n")
cat("  Quasi-Fisher:", fit_qf$aic, "\n")
cat("  Trust Region:", fit_tr$aic, "\n")
cat("  Difference:", abs(fit_tr$aic - fit_qf$aic), "\n")

cat("\nFitted values max difference:", 
    max(abs(fit_tr$fitted.values - fit_qf$fitted.values)), "\n")

cat("\nResiduals max difference:", 
    max(abs(fit_tr$residuals - fit_qf$residuals)), "\n")

cat("\n")


# ============================================================================
# TEST 6: Standard errors and inference
# ============================================================================

cat("TEST 6: Standard errors and inference\n")
cat(separator, "\n")

summary_qf <- summary(fit_qf)
summary_tr <- summary(fit_tr)

cat("\nQuasi-Fisher standard errors:\n")
print(summary_qf$coefficients[, "Std. Error"])

cat("\nTrust Region standard errors:\n")
print(summary_tr$coefficients[, "Std. Error"])

cat("\nDifference in SEs:\n")
print(summary_tr$coefficients[, "Std. Error"] - summary_qf$coefficients[, "Std. Error"])

cat("\n")


# ============================================================================
# SUMMARY
# ============================================================================

cat("\n")
cat(separator, "\n")
cat("TEST SUMMARY\n")
cat(separator, "\n")

# Define success criteria
tolerance <- 1e-4  # Coefficients should agree to 4 decimal places

test_results <- c(
    "Lizards" = max(abs(coef(fit_tr) - coef(fit_qf))) < tolerance,
    "Endometrial" = max(abs(coef(fit_tr2) - coef(fit_qf2))) < tolerance,
    "Separation" = max(abs(coef(fit_tr3) - coef(fit_qf3))) < tolerance,
    "Both converged" = fit_tr$converged & fit_tr2$converged & fit_tr3$converged
)

cat("\nTest results (tolerance = ", tolerance, "):\n", sep = "")
for (i in seq_along(test_results)) {
    cat("  ", names(test_results)[i], ": ", 
        ifelse(test_results[i], "PASS", "FAIL"), "\n", sep = "")
}

cat("\nOverall: ", ifelse(all(test_results), "ALL TESTS PASSED", "SOME TESTS FAILED"), "\n")

cat("\nNote: Small differences expected due to different iteration paths.\n")
cat("Large differences (>", tolerance, ") may indicate implementation issues.\n")